#[test]fn sqlite_snapshot_wfc2d_all_owned_media_and_slot_words(){let s=fixture();let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&actual),d);assert_eq!(actual.slots[0].y.to_bits(),0x7ff0000000000001);assert_eq!(actual.slots[0].pinned_tile_id,Some("".into()));assert_eq!(actual.rules[0].relation,None);assert_eq!(actual.rules[1].relation,Some("".into()));assert!(matches!(actual.tiles[0].media,Wfc2dTileMedia::Empty));assert_eq!(pack::snapshot::ArtifactPack::encode_pack(&actual),pack::snapshot::ArtifactPack::encode_pack(&s));assert_eq!(pack::snapshot::ArtifactDsl::print_dsl(&actual),pack::snapshot::ArtifactDsl::print_dsl(&s));assert_eq!(restore(&project(&Wfc2dSnapshot::default())).unwrap(),Wfc2dSnapshot::default());}
#[test]fn sqlite_snapshot_wfc2d_independent_relations_and_path_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT kind FROM wfc2d_segment ORDER BY ordinal').all().map(r=>r.kind).join(',')!=='Move,Line,Quad,Cubic,Close')throw Error('commands');const pin=d.query('SELECT s.authored_id AS slot,t.authored_id AS tile FROM wfc2d_slot s JOIN wfc2d_tile t ON pinned_tile_id=t.authored_id').get();if(pin.slot!=='box'||pin.tile!=='')throw Error('pin');d.query(\"UPDATE wfc2d_path_color SET red=7 WHERE role='stroke'\").run();await Bun.write(Bun.stdout,d.serialize());";let mut c=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&bytes).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));let actual=restore(&import_sqlite_database(&o.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();if let Wfc2dTileMedia::Vector(Wfc2dVectorMedia {paths})=&actual.tiles[2].media{assert_eq!(paths[0].stroke.unwrap().r,7)}else{panic!("media")}}
#[test]fn sqlite_snapshot_wfc2d_corrupt_graph_and_point_shape(){let d=project(&fixture());for n in 0..8{let mut m=d.clone();match n{0=>m.table_mut("wfc2d_rule").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>m.table_mut("wfc2d_segment").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>m.table_mut("wfc2d_path_color").unwrap().rows[0].values[2]=SqliteValue::Text("unknown".into()),3=>m.table_mut("wfc2d_palette").unwrap().rows[0].values[3]=SqliteValue::Integer(-1),4=>m.table_mut("wfc2d_segment").unwrap().rows[4].values[4]=SqliteValue::Real(1.),5=>m.table_mut("wfc2d_slot_edge").unwrap().rows[0].values[5]=SqliteValue::Integer(999),6=>m.table_mut("wfc2d_slot").unwrap().rows[0].values[8]=SqliteValue::Integer(999),_=>m.table_mut("wfc2d_slot").unwrap().rows[0].values[9]=SqliteValue::Integer(1)};assert!(restore(&m).is_err(),"case {n}");}assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|false,|sqlite_control|fixture().to_sqlite_database(sqlite_control)).is_err());assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits{max_value_bytes:4,..SqliteDatabaseLimits::default()},&mut |_|true,|sqlite_control|Wfc2dSnapshot::from_sqlite_database(&d, sqlite_control)).is_err());}
#[test]fn sqlite_snapshot_wfc2d_actual_native_declaration(){let s=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let provider=codec.snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.wfc2d".into(),standard:"1".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=original_owners::with_encoding(|native_owner|(provider.import)("wfc2d",&dialect, &mut Some(project(&s)),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;let expected=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(pack::snapshot::ArtifactPack::encode_pack(&s)),SnapshotEncoding::Text=>store::io::IoPayload::Text(pack::snapshot::ArtifactDsl::print_dsl(&s))};assert_eq!(actual,expected);assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}let wrong=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.wfc2d".into(),standard:"1".into(),subset:"named".into()};assert!(s.validate_sqlite_snapshot_subset(&wrong,&project(&s),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}

#[test]fn sqlite_snapshot_wfc2d_declared_erased_roundtrip_both_native_encodings(){let source=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let schema=codec.schema.clone();let provider=codec.snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.wfc2d".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<Wfc2dSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<Wfc2dSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&source))};let d=original_owners::with_decoding(|native_owner|(provider.export)(&schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;assert_eq!(project(&restore(&d).unwrap()),project(&source));let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let database=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(original_owners::with_encoding(|native_owner|(provider.import)(&schema,&dialect, &mut Some(database),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value,payload);}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_wfc2d_actual_owned_io_declaration_codec(){use semio_framework_os_kernel::io::{register_native_snapshot_codec,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};register_native_snapshot_codec(crate::WFC_2D_DIALECT,crate::standards::v1::subsets::any::io::io().native.codec).unwrap();let source=fixture();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.wfc.wfc2d".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=async{let original_file_dialect=&dialect;let original_file_input=&source;let original_file_encoding=encoding;let original_file_limits=SqliteDatabaseLimits::default();let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |p|{phases.push(p.phase);true};semio_framework_os_kernel::io::testing::with_snapshot_file_decoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_export_sqlite_snapshot(original_file_dialect,original_file_input,original_file_encoding,sqlite_control,native_owner).await).await}.await.unwrap().value;let back=async{let original_file_dialect=&dialect;let original_file_input=&bytes;let original_file_limits=SqliteDatabaseLimits::default();let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |_|true;semio_framework_os_kernel::io::testing::with_snapshot_file_encoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_import_sqlite_snapshot::<Wfc2dSnapshot>(original_file_dialect,original_file_input,sqlite_control,native_owner).await).await}.await.unwrap().value;assert_eq!(project(&back),project(&source));assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative)));}}

#[test]
fn sqlite_snapshot_wfc2d_retains_native_literal_identity_states(){
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for case in corpus["literalIdentityStates"].as_array().unwrap(){
  let mut source=fixture();for tile in &mut source.tiles{tile.id=case["tileId"].as_str().unwrap().into();}for slot in &mut source.slots{slot.id=case["slotId"].as_str().unwrap().into();slot.pinned_tile_id=Some(case["pinTileId"].as_str().unwrap().into());}for rule in &mut source.rules{rule.id=case["ruleId"].as_str().unwrap().into();rule.tile_a_id=case["tileAId"].as_str().unwrap().into();rule.tile_b_id=case["tileBId"].as_str().unwrap().into();}for edge in &mut source.edges{edge.id=case["edgeId"].as_str().unwrap().into();edge.from_slot_id=case["fromSlotId"].as_str().unwrap().into();edge.to_slot_id=case["toSlotId"].as_str().unwrap().into();}
  let native:[Wfc2dSnapshot;2]=[pack::snapshot::ArtifactPack::decode_pack(&pack::snapshot::ArtifactPack::encode_pack(&source)).unwrap(),pack::snapshot::ArtifactDsl::parse_dsl(&pack::snapshot::ArtifactDsl::print_dsl(&source)).unwrap()];
  for actual in native{assert!(actual.tiles.iter().all(|t|t.id==case["tileId"].as_str().unwrap()));assert!(actual.slots.iter().all(|s|s.id==case["slotId"].as_str().unwrap()&&s.pinned_tile_id.as_deref()==case["pinTileId"].as_str()));assert_eq!(actual.rules[0].tile_a_id,source.rules[0].tile_a_id);assert_eq!(actual.edges[0].from_slot_id,source.edges[0].from_slot_id);}
  let actual=restore(&project(&source)).unwrap();assert_eq!(pack::snapshot::ArtifactPack::encode_pack(&actual),pack::snapshot::ArtifactPack::encode_pack(&source));
 }
}
#[test]
fn sqlite_snapshot_wfc2d_native_real_collection_and_utf_frontiers(){
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let n=corpus["controlledAdmission"]["items"].as_u64().unwrap()as usize;let cancel=corpus["controlledAdmission"]["cancelAfter"].as_u64().unwrap()as usize;
 let mut source=fixture();let first=source.slots[0].clone();source.slots=(0..n).map(|i|{let mut slot=first.clone();slot.id=i.to_string();slot}).collect();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(pack::snapshot::ArtifactPack::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(pack::snapshot::ArtifactDsl::print_dsl(&source))};
  let mut hit=false;let result=original_owners::with_decoding(|native_owner|Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==n&&p.completed==cancel{hit=true;false}else{true}},SqliteDatabaseLimits::default()), native_owner));assert!(result.is_err());assert!(hit);
  let mut hit=false;let result=original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::EncodeNative&&p.total==n&&p.completed==cancel{hit=true;false}else{true}},SqliteDatabaseLimits::default()), native_owner));assert!(result.is_err());assert!(hit);
  assert!(original_owners::with_decoding(|native_owner|Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()}), native_owner)).is_err());assert!(original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()}), native_owner)).is_err());
 }
 source.schema="🧬".repeat(corpus["controlledAdmission"]["textBytes"].as_u64().unwrap()as usize/4);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(pack::snapshot::ArtifactPack::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(pack::snapshot::ArtifactDsl::print_dsl(&source))};
  for phase in[SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{let mut hit=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==phase&&p.total>=65536&&p.completed>=65536&&p.completed<p.total{hit=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let result=if phase==SqliteSnapshotPhase::DecodeNative{original_owners::with_decoding(|native_owner|Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut control, native_owner)).map(|_|())}else{original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut control, native_owner)).map(|_|())};assert!(result.is_err());assert!(hit);}
  let limits=SqliteDatabaseLimits{max_value_bytes:corpus["controlledAdmission"]["smallValueBudget"].as_u64().unwrap()as usize,..SqliteDatabaseLimits::default()};assert!(original_owners::with_decoding(|native_owner|Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).is_err());assert!(original_owners::with_encoding(|native_owner|source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).is_err());
 }
}

use semio_s_wfc_sqlite_bitmap::pixel_laws as bitmap_pixel_tests;
#[test]
fn sqlite_snapshot_wfc2d_canonical_pixels_and_full_literal_owner_states(){
 let contract:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🪶️sqlite/🎨️bitmap/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for case in contract["cases"].as_array().unwrap(){
  let mut source=fixture();let Wfc2dTileMedia::Bitmap(Wfc2dBitmapMedia {width,height,pixels,..})=&mut source.tiles[1].media else{panic!("authored bitmap owner")};
  *width=u32::try_from(case["width"].as_u64().unwrap()).unwrap();*height=u32::try_from(case["height"].as_u64().unwrap()).unwrap();*pixels=case["text"].as_str().unwrap().into();
  let mut edited=source.clone();let expected=if case["id"]=="three-unknown-index"{let Wfc2dTileMedia::Bitmap(Wfc2dBitmapMedia {pixels,..})=&mut edited.tiles[1].media else{panic!("authored bitmap owner")};*pixels="AP//".into();Some(&edited)}else{None};
  bitmap_pixel_tests::verify(&source,expected,"wfc2d",case);
 }
}
